%[text] ## Numerical Solver for Radial KS-PBE
%[text] The remainder of the live script contains the solver. The exchange-correlation block in the original lecture is replaced by PBE exchange together with PBE correlation built on top of the PW92 local correlation energy. The rest is kept the same.
function Hr_uk = Hamiltonian(S,uk)
    Hr_uk = -1/2*S.Lap*uk + S.Veff.*uk;
end
function S = compute_effective_potential(S,rho)
    rho = max(rho,S.rhoFloor);
    S.Vh = compute_hartree_potential(S,rho);
    [S.ExDensity,S.Vx] = pbe_exchange(S,rho);
    [S.EcDensity,S.Vc] = pbe_correlation(S,rho);
    S.Veff = S.Vext + S.Vh + S.Vx + S.Vc;
end
function rho = electron_density(S,u)
    R = u./S.r;
    rho = sum(R.^2.*S.occ,2)/(4*pi);
end
function Vh = compute_hartree_potential(S,rho)
    phi = S.Lap\(-4*pi*rho.*S.r);
    Vh = phi./S.r;
end
function intf = int3d(S,f)
    intf = 4*pi*S.h*sum(f.*S.r.^2);
end
function S = energy(S)
    S.Ek = sum(sum((-1/2*S.Lap*S.u).*S.u).*S.occ)*S.h;
    S.Eext = int3d(S,S.Vext.*S.rho);
    S.Eh = 1/2*int3d(S,S.Vh.*S.rho);
    S.Ex = int3d(S,S.ExDensity.*S.rho);
    S.Ec = int3d(S,S.EcDensity.*S.rho);
    S.Exc_dc = int3d(S,(S.Vx+S.Vc).*S.rho);
    S.Etot = sum(S.occ.*S.Eband') - S.Eh - S.Exc_dc + S.Ex + S.Ec;
end
function u = normalize(S,u)
    scale = S.h*sum(u.^2,1);
    u = u./sqrt(scale);
end
function S = SCF(S)
    R0 = exp(-S.Z*S.r);
    S.u = normalize(S,R0.*S.r);
    S.rho = electron_density(S,S.u);
    Etot_prev = inf;
    step = 0;
    maxstep = 200;
    beta = 0.35;
    while abs(Etot_prev-S.Etot) > S.tol && step < maxstep
        Etot_prev = S.Etot;
        S = compute_effective_potential(S,S.rho);
        [S.u,S.Eband] = eigSolve(S);
        rho_new = electron_density(S,S.u);
        S.rho = (1-beta)*rho_new + beta*S.rho;
        S = energy(S);
        step = step + 1;
        if mod(step,10) == 0 || step == 1
            disp("Step " + step + ": Etot = " + num2str(S.Etot,'%.8f') + " Ha")
        end
    end
    disp("Finished SCF in " + step + " steps.")
end
function [u,Eband] = eigSolve(S)
    opts = struct(maxit=5000,tol=S.tol,isreal=1);
    Hfun = @(x) Hamiltonian(S,x);
    [u,Eband] = eigs(Hfun,S.Nd,S.Nband,'smallestreal',opts);
    Eband = diag(Eband);
    u = normalize(S,u);
end
function S = init_DFT(Z,R_MAX,Nd,tol,FDn)
    S = struct();
    S.Z = Z;
    S.Nd = Nd;
    S.h = R_MAX/Nd;
    S.r = linspace(S.h,R_MAX,Nd)';
    S.FDn = FDn;
    S.tol = tol;
    S.rhoFloor = 1e-10;
    S.gradFloor = 1e-12;
    S.Nband = ceil(S.Z/2);
    S.occ = [2*ones(1,floor(S.Z/2)) ones(1,mod(S.Z,2))];
    S.Etot = 0;
    S.Vext = -S.Z./S.r;
    S.Lap = Laplacian(S.FDn,S.Nd,S.h);
end
%%
%[text] ## PBE Exchange-Correlation Functions
%[text] The helper functions below evaluate the PBE exchange and correlation energy per electron and reconstruct the radial GGA potential through the Euler-Lagrange expression written at the start of the live script.
function [ex,vx] = pbe_exchange(S,rho)
    drho = radial_derivative(S,rho);
    ex = pbe_exchange_energy_density(rho,drho,S.rhoFloor,S.gradFloor);
    vx = gga_potential(S,rho,drho,@(rhoVal,gradVal) ...
        pbe_exchange_energy_density(rhoVal,gradVal,S.rhoFloor,S.gradFloor));
end
function [ec,vc] = pbe_correlation(S,rho)
    drho = radial_derivative(S,rho);
    ec = pbe_correlation_energy_density(rho,drho,S.rhoFloor,S.gradFloor);
    vc = gga_potential(S,rho,drho,@(rhoVal,gradVal) ...
        pbe_correlation_energy_density(rhoVal,gradVal,S.rhoFloor,S.gradFloor));
end
function epsx = pbe_exchange_energy_density(rho,drho,rhoFloor,gradFloor)
    rhoSafe = max(rho,rhoFloor);
    gradMag = sqrt(drho.^2 + gradFloor^2);
    kF = (3*pi^2*rhoSafe).^(1/3);
    s = gradMag./(2*kF.*rhoSafe);
    kappa = 0.804;
    mu = 0.2195149727645171;
    Fx = 1 + kappa - kappa./(1 + mu*s.^2/kappa);
    Cx = 0.7385587663820223;
    epsx = -Cx*rhoSafe.^(1/3).*Fx;
end
function epsc = pbe_correlation_energy_density(rho,drho,rhoFloor,gradFloor)
    rhoSafe = max(rho,rhoFloor);
    gradMag = sqrt(drho.^2 + gradFloor^2);
    ecLDA = pw92_correlation(rhoSafe);
    kF = (3*pi^2*rhoSafe).^(1/3);
    kS = sqrt(4*kF/pi);
    t = gradMag./(2*kS.*rhoSafe);
    gamma = 0.0310906908696549;
    beta = 0.0667245506031492;
    A = beta/gamma./max(exp(-ecLDA/gamma)-1,1e-14);
    H = gamma*log(1 + (beta/gamma)*t.^2.*(1 + A.*t.^2)./(1 + A.*t.^2 + A.^2.*t.^4));
    epsc = ecLDA + H;
end
function ec = pw92_correlation(rho)
    rs = (3./(4*pi*rho)).^(1/3);
    A = 0.0310907;
    alpha1 = 0.21370;
    beta1 = 7.5957;
    beta2 = 3.5876;
    beta3 = 1.6382;
    beta4 = 0.49294;
    sqrtRs = sqrt(rs);
    q = 2*A*(beta1*sqrtRs + beta2*rs + beta3*rs.*sqrtRs + beta4*rs.^2);
    ec = -2*A*(1 + alpha1*rs).*log(1 + 1./q);
end
function v = gga_potential(S,rho,drho,epsHandle)
    rhoSafe = max(rho,S.rhoFloor);
    deltaRho = max(1e-8,1e-5*rhoSafe);
    rhoPlus = rhoSafe + deltaRho;
    rhoMinus = max(rhoSafe - deltaRho,S.rhoFloor);
    fPlus = rhoPlus.*epsHandle(rhoPlus,drho);
    fMinus = rhoMinus.*epsHandle(rhoMinus,drho);
    dfdrho = (fPlus - fMinus)./(rhoPlus - rhoMinus);
    deltaGrad = max(1e-8,1e-5*max(1,abs(drho)));
    fGradPlus = rhoSafe.*epsHandle(rhoSafe,drho + deltaGrad);
    fGradMinus = rhoSafe.*epsHandle(rhoSafe,drho - deltaGrad);
    dfdgrad = (fGradPlus - fGradMinus)./(2*deltaGrad);
    v = dfdrho - radial_divergence(S,dfdgrad);
end
function dfdr = radial_derivative(S,f)
    if isvector(f)
        dfdr = gradient(f,S.h);
    else
        dfdr = zeros(size(f));
        for idx = 1:size(f,2)
            dfdr(:,idx) = gradient(f(:,idx),S.h);
        end
    end
end
function divf = radial_divergence(S,fr)
    divf = radial_derivative(S,S.r.^2.*fr)./(S.r.^2);
end
%%
%[text] ## Finite-Difference Operators
function Lap = Laplacian(FDn,Nd,h)
    w2 = w2_c(FDn);
    e = ones(Nd,1)/h^2;
    Lap = spdiags(w2(1)*e,0,Nd,Nd);
    for i = 1:FDn
        Lap = Lap + spdiags(w2(i+1)*e,i,Nd,Nd);
        Lap = Lap + spdiags(w2(i+1)*e,-i,Nd,Nd);
    end
end
function w2 = w2_c(FDn)
    w2 = zeros(1,FDn+1);
    for k = 1:FDn
        w2(k+1) = (2*(-1)^(k+1))*(factorial(FDn)^2)/(k*k*factorial(FDn-k)*factorial(FDn+k));
        w2(1) = w2(1) - 2/(k*k);
    end
end

